class Dhcp:
    def __init__(
        self,
        preferred_address_family: str | None = None,
        management_poolv4: str | None = None,
        management_poolv6: str | None = None,
        dhcp4_options: list[Dhcp4Options] | None = None,
        dhcp6_options: list[Dhcp6Options] | None = None,
    ):
        self.preferred_address_family = preferred_address_family
        self.management_poolv4 = management_poolv4
        self.management_poolv6 = management_poolv6
        self.dhcp4_options = dhcp4_options
        self.dhcp6_options = dhcp6_options

    def to_input(self):
        _rval = {}
        if self.preferred_address_family is not None:
            _rval[constants.Y_PREFERREDADDRESSFAMILY] = self.preferred_address_family
        if self.management_poolv4 is not None:
            _rval[constants.Y_MANAGEMENTPOOLV4] = self.management_poolv4
        if self.management_poolv6 is not None:
            _rval[constants.Y_MANAGEMENTPOOLV6] = self.management_poolv6
        if self.dhcp4_options is not None:
            _rval[constants.Y_DHCP4OPTIONS] = [x.to_input() for x in self.dhcp4_options]
        if self.dhcp6_options is not None:
            _rval[constants.Y_DHCP6OPTIONS] = [x.to_input() for x in self.dhcp6_options]
        return _rval

    @staticmethod
    def from_input(obj) -> "Dhcp | None":
        if not obj:
            return None
        _preferred_address_family = obj.get(constants.Y_PREFERREDADDRESSFAMILY)
        _management_poolv4 = obj.get(constants.Y_MANAGEMENTPOOLV4)
        _management_poolv6 = obj.get(constants.Y_MANAGEMENTPOOLV6)
        _dhcp4_options = []
        if obj.get(constants.Y_DHCP4OPTIONS) is not None:
            for _e in obj.get(constants.Y_DHCP4OPTIONS):
                _dhcp4_options.append(Dhcp4Options.from_input(_e))
        _dhcp6_options = []
        if obj.get(constants.Y_DHCP6OPTIONS) is not None:
            for _e in obj.get(constants.Y_DHCP6OPTIONS):
                _dhcp6_options.append(Dhcp6Options.from_input(_e))
        return Dhcp(
            preferred_address_family=_preferred_address_family,
            management_poolv4=_management_poolv4,
            management_poolv6=_management_poolv6,
            dhcp4_options=_dhcp4_options,
            dhcp6_options=_dhcp6_options,
        )


